    ["size", ["[]", "PRIVATE_DIAGNOSTIC_BYTES"], "PRIVATE_DIAGNOSTIC_BYTES", "exceeds the authoritative byte size"],
  ] as const)("refuses an indexed artifact whose materialized %s is corrupt across chunks", async (
    _case,
